import pandas as pd, numpy as np
path='/Users/mac/Documents/学习/找工作/SolveX/bench/sessions/r7-c3-submit-mwp2gic2/data/2026_MCM_Problem_C_Data.csv'
df = pd.read_csv(path, keep_default_na=False, na_values=[''])

for s, wk in [(1,6),(3,10)]:
    g = df[(df.season==s)]
    print(f"\n=== Season {s}, week {wk} ===")
    for _,r in g.iterrows():
        vals = [str(r[f'week{wk}_judge{j}_score']) for j in range(1,5) if f'week{wk}_judge{j}_score' in df.columns]
        print(f"{str(r.celebrity_name)[:22]:24} {str(r.results)[:17]:18} -> {vals}")

# per-season week-level judge count
print("\nPer (season,week): how many judge cols numeric>0 across all rows")
rows=[]
for s,g in df.groupby('season'):
    cnt_by_wk={}
    for w in range(1,12):
        for j in range(1,5):
            c=f'week{w}_judge{j}_score'
            if c in df.columns:
                nn = (g[c].astype(str).map(lambda x: x not in ('N/A','nan','0'))).sum()
                if nn>0: cnt_by_wk[j]=max(cnt_by_wk.get(j,0), w)
    rows.append((int(s), cnt_by_wk))
